    sourceBook: "Advanced Player's Guide",
    category: "Combat",
    supportabilityStatus: "supported",
    effectType: null,
    prerequisites: [{"type":"feat","key":"Improved Reposition","value":null},{"type":"bab","key":null,"value":6}],
