    sourceBook: "Ultimate Combat",
    category: "Untyped",
    supportabilityStatus: "supported",
    effectType: null,
    prerequisites: [{"type":"feat","key":"Dimensional Assault","value":null},{"type":"bab","key":null,"value":6}],
