    category: "Untyped",
    supportabilityStatus: "unsupported",
    effectType: null,
    prerequisites: [{"type":"unsupported","key":"Heal 5 ranks","value":null},{"type":"unsupported","key":"delayed bomb alchemist discovery","value":null}],
